Surface opSubtraction(Surface d1, Surface d2)
{
    if (-d1.sd > d2.sd)
        return Surface(-d1.sd, d1.mat);
    return d2;
}
Surface opUnion(Surface d1, Surface d2)
{
    if (d1.sd < d2.sd)
        return d1;
    return d2;
}
Surface sdSphere( vec3 p, float s, vec3 offset, Material mat)
{
    p -= offset;
    float d = length(p)-s;
    return Surface(d, mat);
}

Surface sdRoundedCylinder( vec3 p, float ra, float rb, float h, vec3 offset, mat3 transform, Material mat)
{
    p = (p - offset) * transform;
    vec2 d = vec2( length(p.xz)-2.0*ra+rb, abs(p.y) - h );
    return Surface(min(max(d.x,d.y),0.0) + length(max(d,0.0)) - rb, mat);
}

// tank body
Surface sdBox( vec3 p, vec3 b, vec3 offset, vec3 col, mat3 transform)
{
    p = (p - offset) * transform;
    vec3 q = abs(p) - b;
    float d = length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
    return Surface(d, M_Army());
}
// explosion from hit
Surface sdExplosion(vec3 p, float alpha, vec3 offset, float power, float displacementPower)
{
    float radius = mix(0.0, power, alpha);
    float explosion = sdSphere(p, radius, offset, M_TankTire()).sd;
    float d = displacementPower * sin(1.*p.x + 2.0*iTime)*sin(1.*p.y + 2.0*iTime)*sin(1.*p.z + 2.0*iTime);
    return Surface(explosion + d , M_Explosion(p));
}
// explosion from shooting. can be united as one function but i don't want to
Surface sdExplosionShot(vec3 p, float alpha, vec3 offset, float power, float displacementPower)
{
    float radius = mix(0.0, power, alpha);
    float explosion = sdSphere(p, radius, offset, M_Explosion(p)).sd;
    float d = displacementPower * sin(3.5*p.x + iTime)*sin(3.5*p.y + iTime)*sin(3.5*p.z + iTime);
    return Surface(explosion + d , M_Explosion(p));
}
// same explosion, same reason existing here
Surface sdBigSmoke(vec3 p, float alpha, vec3 offset, float power)
{
    float radius = mix(0.0, power, alpha);
    float explosion = sdSphere(p, radius, offset, M_BigSmoke(p)).sd;
    float d = sin(3.*p.x + 5.*iTime)*sin(3.*p.y + 5.*iTime)*sin(3.*p.z + 5.*iTime);
    return Surface(explosion + d, M_BigSmoke(p));
}
// tank tires
Surface sdLink( vec3 p, float le, float r1, float r2, vec3 offset, vec3 col, mat3 transform, vec3 offsetRot )
{
    p = (p - offset) * transform - offsetRot;
    vec3 q = vec3( p.x, max(abs(p.y)-le,0.0), p.z );
    float d = length(vec2(length(q.xy)-r1,q.z)) - r2;
    return Surface(d, M_TankTire());
}
// tank gun
Surface sdCapsule( vec3 p, vec3 a, vec3 b, float r, vec3 offset, vec3 col, mat3 transform )
{
    p = (p - offset) * transform; // apply transformation matrix
    vec3 pa = p - a, ba = b - a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    float d = length( pa - ba*h ) - r;
    return Surface(d, M_Army());
}
// tower and gun 
Surface sdTower(vec3 p, vec3 locationOffset, vec2 rotationTower, float rotationTank)
{
    Surface d1 = sdBox(p, SIZE_TANK_TOWER, OFFSET_TANK_TOWER + locationOffset, vec3(0, 1, 0),
                       identity() * rotateY(rotationTank) * rotateY(rotationTower.x)); // tower
    Surface d2 = sdCapsule(p, vec3(0), vec3(4, 0, 0), 0.3, vec3(0, 1.6, 0) + locationOffset, vec3(0, 0, 0),
                           identity() * rotateY(rotationTank) * rotateY(rotationTower.x) * rotateZ(rotationTower.y)); // gun
    return opUnion(d1, d2);
}
// tank body, tires, tower
Surface sdTank(vec3 p, vec3 locationOffset, float rotationTank, vec2 rotationTower)
{
    Surface d1 = sdBox(p, SIZE_TANK_BODY, OFFSET_TANK_BODY + locationOffset, vec3(0, 1, 0), identity() * rotateY(rotationTank)); // body
    Surface d2 = sdLink(p, LENGTH_TANK_LINK, RADIUS_TANK_LINK, BOLDNESS_TANK_LINK, locationOffset, vec3(0, 0, 0), 
                        identity() * rotateY(rotationTank) * rotateZ(PI/2.0), OFFSET_TANK_LINK_RIGHT); // link right
    d1 = opUnion(d1, d2);
    d2 = sdLink(p, LENGTH_TANK_LINK, RADIUS_TANK_LINK, BOLDNESS_TANK_LINK, locationOffset, vec3(0, 0, 0),
                identity() * rotateY(rotationTank) * rotateZ(PI/2.0), OFFSET_TANK_LINK_LEFT); // link left
    d1 = opUnion(d1, d2);

    // TODO WHEELS
    // sdRoundedCylinder
    d2 = sdTower(p, locationOffset, rotationTower, rotationTank);
    d1 = opUnion(d1, d2);
    return d1;
}

