// predicting projectile trajectory
// draws spheres per tick approximation
// abomination.
Surface sdTrajectory(vec3 p)
{
    vec2 locationTank = fetchData(iChannel0, PlayerPositionData).xy;
    float rotationTank = fetchData(iChannel0, PlayerPositionData).z;
    vec2 rotationTower = fetchData(iChannel0, WeaponData).xy;
    vec3 ProjectileLocation = vec3(locationTank.x, 0, locationTank.y);
    vec3 VelocityVector = rotateY(rotationTank)*rotateY(rotationTower.x)*rotateZ(rotationTower.y) 
                          * (ShootSocketOffset + vec3(0, rotationTower.y / 2.0, 0));
    vec3 ProjectileVelocity = rotateY(rotationTank) * rotateY(rotationTower.x) * rotateZ(rotationTower.y) * vec3(5, 0, 0);
    ProjectileLocation += VelocityVector;

    Surface d = sdSphere(p, .3, ProjectileLocation, M_Trajectory(p)); // first step - shell spawn location

    // god this is worse than the invasion of angola by the soviets in 1988
    float ApproxTick = 1.0 / round(iFrameRate);
    float ApproxFrameRate = round(iFrameRate);
    for (int i = 0; i < 30; i++)
    {
        for (int j = 0; j < 5; j++) // increases approximation steps - draws every Nth steps. more fps - more trajectory balls. TODO fix
        {
            ProjectileVelocity += GRAVITY * ApproxTick;
            ProjectileLocation += ProjectileVelocity * ApproxTick * ProjectileSpeed;
        }

        Surface part = sdSphere(p, .3, ProjectileLocation, M_Trajectory(p));
        d = opUnion(d, part);
    }
    return d;
}

Surface minWithColor(Surface obj1, Surface obj2)
{
    if (obj2.sd < obj1.sd)
        return obj2;
    return obj1;
}

Surface sdScene(vec3 p)
{
    vec3 floorColor = vec3(1. + 0.7*mod(floor(p.x) + floor(p.z), 2.0));
    Surface co = sdFloor(p, floorColor);

    vec3 locationOffset = vec3(fetchData(iChannel0, PlayerPositionData).x, 0, fetchData(iChannel0, PlayerPositionData).y);
    float rotationTank = fetchData(iChannel0, PlayerPositionData).z;
    vec2 rotationTower = fetchData(iChannel0, WeaponData).xy;
    co = minWithColor(co, sdTank(p, locationOffset, rotationTank, rotationTower));

    vec3 locationOffsetEnemy = vec3(fetchData(iChannel0, EnemyData).x, 0.0, fetchData(iChannel0, EnemyData).y);
    float rotationTankEnemy = fetchData(iChannel0, EnemyData).z;
    vec2 rotationTowerEnemy = vec2(fetchData(iChannel0, EnemyData).w, 0);
    co = minWithColor(co, sdTank(p, locationOffsetEnemy, rotationTankEnemy, rotationTowerEnemy));
    if (fetchData(iChannel0, WeaponData).z == 1.0)
        co = minWithColor(co, sdTrajectory(p));

    float ShotKD = fetchData(iChannel0, ProjectileData).w;
    vec3 offset = fetchData(iChannel0, ProjectileData).xyz;
    if (ShotKD > 0.0)
    {
        co = minWithColor(co, sdSphere(p, 0.5, offset, M_TankTire()));

        vec3 VelocityVector = rotateY(rotationTank) * rotateY(rotationTower.x) * rotateZ(rotationTower.y) * ShootSocketOffset;
        if (ShotKD > 0.2)
        {
            co = minWithColor(co, sdBigSmoke(p, 0.5, locationOffset + VelocityVector, ShotKD));
            if (ShotKD > 0.7)
                co = minWithColor(co, sdExplosionShot(p, 0.5, locationOffset + VelocityVector, ShotKD, 0.75));
        }
    }

    vec4 Explosion = fetchData(iChannel0, ExplosionData);
    if (Explosion.w > 0.0)
    {
        co = minWithColor(co, sdExplosion(p, 0.5, Explosion.xyz, Explosion.w, 1.0));
    }
    return co;
}

Surface rayMarch(vec3 ro, vec3 rd, float start, float end)
{
    float depth = start;
    Surface co; // closest object

    for (int i = 0; i < MAX_MARCHING_STEPS; i++)
    {
        vec3 p = ro + depth * rd;
        co = sdScene(p);
        depth += co.sd;
        if (co.sd < PRECISION || depth > end)
            break;
    }

    co.sd = depth;
    return co;
}

vec3 calcNormal(in vec3 p)
{
    vec2 e = vec2(1, -1) * EPSILON;
    return normalize(
      e.xyy * sdScene(p + e.xyy).sd +
      e.yyx * sdScene(p + e.yyx).sd +
      e.yxy * sdScene(p + e.yxy).sd +
      e.xxx * sdScene(p + e.xxx).sd);
}

mat3 camera(vec3 cameraPos, vec3 lookAtPoint)
{
    vec3 cd = normalize(lookAtPoint - cameraPos); // camera direction
    vec3 cr = normalize(cross(vec3(0, 1, 0), cd)); // camera right
    vec3 cu = normalize(cross(cd, cr)); // camera up

    return mat3(-cr, cu, -cd);
}

vec3 phong(vec3 lightDir, vec3 normal, vec3 rd, Material mat)
{
    //ambient
    vec3 ambient = mat.ambientColor;

    //diffusion
    float dotLN = clamp(dot(lightDir, normal), 0., 1.);
    vec3 diffuse =  dotLN * mat.diffuseColor;

    //specular
    vec3 R = reflect(lightDir, normal);
    vec3 V = -rd;
    float dotVR = clamp(dot(V, R), 0., 1.);
    vec3 specular = pow(dotVR, mat.alpha) * mat.specularColor;

    return ambient + diffuse + specular;
}

Surface rayMarch(vec3 ro, vec3 rd)
{
    float depth = MIN_DIST;

    Surface obj;

    for (int i = 0; i < MAX_MARCHING_STEPS; i++)
    {
        vec3 p = ro + depth * rd;
        obj = sdScene(p);
        depth += obj.sd;
        if (obj.sd < PRECISION || depth > MAX_DIST)
            break;
    }
    obj.sd = depth;
    return obj;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
    vec2 mouseUV = iMouse.xy/iResolution.xy; // Range: <0, 1>
    vec3 backgroundColor = vec3(0.835, 1, 1);

    vec3 col = vec3(0);
    vec3 lp = vec3(fetchData(iChannel0, PlayerPositionData).x, 0, fetchData(iChannel0, PlayerPositionData).y); // camera target
    vec3 ro = vec3(0, 8, 0); // ray origin that represents camera position

    float cameraRadius = 2.;
    ro.yz = ro.yz * cameraRadius * rotate2d(mix(PI/2., 0., mouseUV.y));
    ro.xz = ro.xz * rotate2d(mix(-PI, PI, mouseUV.x)) + vec2(lp.x, lp.z);

    vec3 rd = camera(ro, lp) * normalize(vec3(uv, -1)); // ray direction

    Surface co = rayMarch(ro, rd, MIN_DIST, MAX_DIST); // closest object

    if (co.sd > MAX_DIST)
        col = backgroundColor; // ray didn't hit anything
    else
    {
        vec3 p = ro + rd * co.sd;
        vec3 normal = calcNormal(p);

        vec3 lightPosition1 = vec3(0, 10, 0);
        vec3 lightDirection1 = normalize(lightPosition1 - p);
        float lightIntensity1 = 0.8;

        col = lightIntensity1 * phong(lightDirection1, normal, rd, co.mat);

        vec4 Explosion = fetchData(iChannel0, ExplosionData);
        if (Explosion.w > 0.0)
        {
            vec3 lightPositionExplosion = Explosion.xyz;
            vec3 lightDirectionExplosion = normalize(lightPositionExplosion - p);
            float lightIntensityExplosion = clamp(Explosion.w - 0.5, 0.0, 1.0);
            col += lightIntensityExplosion * (phong(lightDirectionExplosion, normal, rd, co.mat));
        }

     }

  fragColor = vec4(col, 1.0);
}

