float ProcessMovementInput()
{
    float forward = texelFetch(iChannel1, ivec2(KEY_W, 0), 0).x * 1.0;
    float backward = texelFetch(iChannel1, ivec2(KEY_S, 0), 0).x * -1.0;

    return (forward + backward);
}
float ProcessRotationInput()
{
    float right = texelFetch(iChannel1, ivec2(KEY_D, 0), 0).x * 1.0;
    float left = texelFetch(iChannel1, ivec2(KEY_A, 0), 0).x * -1.0;

    return (left + right);
}
vec2 ProcessTowerInput()
{
    vec2 up = texelFetch(iChannel1, ivec2(KEY_ARROW_UP, 0), 0).x * vec2(0.0, -1.0);
    vec2 right = texelFetch(iChannel1, ivec2(KEY_ARROW_RIGHT, 0), 0).x * vec2(1.0, 0.0);
    vec2 down = texelFetch(iChannel1, ivec2(KEY_ARROW_DOWN, 0), 0).x * vec2(0.0, 1.0);
    vec2 left = texelFetch(iChannel1, ivec2(KEY_ARROW_LEFT, 0), 0).x * vec2(-1.0, 0.0);

    return (up + right + down + left);
}
float casin(float x) {
	float negate = float(x < 0.0);
	x = abs(x);
	float ret = -0.0187293;
	ret *= x;
	ret += 0.0742610;
	ret *= x;
	ret -= 0.2121144;
	ret *= x;
	ret += 1.5707288;
	ret = 3.14159265358979*0.5 - sqrt(1.0 - x)*ret;
	return ret - 2.0 * negate * ret;
}
float atan2(float y, float x)
{
 	float absx, absy, val;

     if (x == 0.0 && y == 0.0)
     {
 		return 0.0;
 	}
 	absy = y < 0.0 ? -y : y;
 	absx = x < 0.0 ? -x : x;
 	if (absy - absx == absy) {
 		return y < 0.0 ? -3.1415*2.0 : 3.1415*2.0;
 	}

    if (absx - absy == absx) {
		val = 0.0;
    } else {
        val = casin((y/x)/sqrt(1.0+((y/x)*(y/x))));
    }
 	if (x > 0.0) {
 		return val;
 	}
 	if (y < 0.0) {
		return val - 3.1415;
 	}
 	return val + 3.1415;
}
float angleDegToRad(float angle)
{
    return angle / 180.0 * PI;
}
float getAngle(float x, float y)
{
    if (x == 0.)
    {
        if (y > 0.)
            return angleDegToRad(90.0);
        if (y == 0.)
            return angleDegToRad(0.0);
        return angleDegToRad(270.0);
    }
    if (y == 0.)
    {
        if (x > 0.)
            return angleDegToRad(0.0);
        return angleDegToRad(180.0);
    }
    float angle = atan2(y, x) / PI * 180.0;
    return angleDegToRad(angle);
}

// basic prng for deciding next enemy spawn coords
