vec2 GenerateEnemyCoords()
{
    float x = rand();
    if (abs(x) < 15.0)
        x += sign(x)*15.0;
    float y = rand();
    if (abs(y) < 15.0)
        y += sign(y)*15.0;
    vec2 result = vec2(x, y);

    return result;
}

int bHasHitEnemy()
{
    vec4 ExtractedProjectileData = fetchData(iChannel0, ProjectileData);
    vec2 EnemyPosition = fetchData(iChannel0, EnemyData).xy;
    if (ExtractedProjectileData.x >= EnemyPosition.x - HitRadius && ExtractedProjectileData.x <= EnemyPosition.x + HitRadius)
    {
        if (ExtractedProjectileData.z >= EnemyPosition.y - HitRadius && ExtractedProjectileData.z <= EnemyPosition.y + HitRadius)
        {
            if (ExtractedProjectileData.y < HitZLimit)
            {
                return 1;
            }
        }
    }
    return 0;
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    setNSeed();
    if (iFrame == 0)
    {
        if (storeData(fragCoord, PlayerPositionData))
        {
            fragColor = vec4(0);
        }
        if (storeData(fragCoord, WeaponData))
        {
            fragColor = vec4(0);
        }
        if (storeData(fragCoord, EnemyData))
        {
            vec2 v1 = fetchData(iChannel0, PlayerPositionData).xy;
            vec2 v2 = GenerateEnemyCoords();
            float rot = mod( atan(v1.x,v1.y) -atan(v2.x,v2.y), PI); // doesn't work properly but looks funny sometimes
            fragColor = vec4(v2, rot, 0);
        }
        if (storeData(fragCoord, ProjectileData))
        {
            fragColor = vec4(0);
        }
        if (storeData(fragCoord, ProjectileVelocityData))
        {
            fragColor = vec4(0);
        }
        if (storeData(fragCoord, ExplosionData))
        {
            fragColor = vec4(0);
        }
    }
    if (iFrame > 0) // frame process
    {
        if (storeData(fragCoord, PlayerPositionData))
        {
            vec4 ExtractedPlayerPositionData = fetchData(iChannel0, PlayerPositionData);
            vec2 PlayerPosition = ExtractedPlayerPositionData.xy;
            float PlayerRotation = ExtractedPlayerPositionData.z;

            float FrameMovement = ProcessMovementInput();
            float FrameRotation = ProcessRotationInput();

            vec2 PlayerMovement = (forwardV * rotateY(-PlayerRotation)).xz * FrameMovement * 0.1;

            vec2 EnemyPosition = fetchData(iChannel0, EnemyData).xy;
            float EnemyRotation = fetchData(iChannel0, EnemyData).z;
            vec2 Offset = abs(rotateY(EnemyRotation) * vec3(5, 2.5, 0)).xz;
            vec2 EnemyMaxCoord = EnemyPosition + Offset;
            vec2 EnemyMinCoord = EnemyPosition - Offset;

            vec2 PlayerPredictedLocation = PlayerPosition + PlayerMovement;
            vec2 PlayerOffset = abs(rotateY(PlayerRotation) * vec3(5, 2.5, 0)).xz;
            vec2 PlayerMaxCoord = PlayerPredictedLocation + PlayerOffset;
            vec2 PlayerMinCoord = PlayerPredictedLocation - PlayerOffset;

            // if enemy doesn't obstruct - allows movement
            // comparing min/max between two rectangles
            if (PlayerMaxCoord.x < EnemyMinCoord.x
                || PlayerMinCoord.x > EnemyMaxCoord.x
                || PlayerMaxCoord.y < EnemyMinCoord.y
                || PlayerMinCoord.y > EnemyMaxCoord.y)
                PlayerPosition += PlayerMovement * TankSpeed * iTimeDelta;
            PlayerRotation += FrameRotation * (TankRotationMultiplier * iTimeDelta); // can clip into the enemy tank. wnf
            fragColor = vec4(PlayerPosition, PlayerRotation, 0);

        }
        if (storeData(fragCoord, WeaponData))
        {
            vec4 ExtractedWeaponData = fetchData(iChannel0, WeaponData);
            vec2 WeaponRotation = ExtractedWeaponData.xy;
            float ShowTrajectory = ExtractedWeaponData.z;
            float TrajectoryTimeOut = ExtractedWeaponData.w;
            vec2 RotationDelta = ProcessTowerInput();

            float SpeedHorizontal = RotationDelta.x * TankTowerRotationMultiplierHorizontal * iTimeDelta;
            float SpeedVertical = RotationDelta.y * TankTowerRotationMultiplierVertical * iTimeDelta;
            WeaponRotation.x += SpeedHorizontal;
            if (abs(WeaponRotation.y + SpeedVertical) < MAX_WEAPON_ANGLE_Z && (WeaponRotation.y + SpeedVertical) < 0.0)
                WeaponRotation.y += SpeedVertical;
            else
            {
                if (abs(WeaponRotation.y + SpeedVertical) >= MAX_WEAPON_ANGLE_Z)
                    WeaponRotation.y = -MAX_WEAPON_ANGLE_Z; // only stalin knows why this rotation is negative
                if (abs(WeaponRotation.y + SpeedVertical) <= 0.0)
                    WeaponRotation.y = 0.0;
            }

            float keyState = texelFetch(iChannel1, ivec2(KEY_C, 0), 0).x;
            if (keyState == 1.0 && TrajectoryTimeOut <= 0.0)
            {
                ShowTrajectory = ShowTrajectory == 0.0 ? 1.0 : 0.0;
                TrajectoryTimeOut = 0.2; // otherwise would blink - button is pressed between multiple frames
            }
            if (TrajectoryTimeOut > 0.0)
                TrajectoryTimeOut -= iTimeDelta;

            fragColor = vec4(WeaponRotation, ShowTrajectory, TrajectoryTimeOut);      
        }
        if (storeData(fragCoord, EnemyData))
        {
            vec4 ExtractedEnemyData = fetchData(iChannel0, EnemyData);
            vec2 EnemyPosition = ExtractedEnemyData.xy;

            vec2 PlayerPosition = fetchData(iChannel0, PlayerPositionData).xy;
            // calculating angle between player and enemy
            // i sincerely have no idea why it works

            // the bear got into the burning car
            // the bear has burnt
            // peak russian humour with peak russian maths
            float kostyl = ExtractedEnemyData.z >= PI/2. ? 3.0 : 1.0;
            float angle = getAngle(PlayerPosition.x - EnemyPosition.x, PlayerPosition.y - EnemyPosition.y)
                                    + kostyl * MAGIC_ANGLE_KOSTYL; // it's better not to talk about this. TODO fix, crappy hack
            ExtractedEnemyData.xy = EnemyPosition;
            ExtractedEnemyData.w = angle;

            if (bHasHitEnemy() == 1)
                ExtractedEnemyData.xy = GenerateEnemyCoords(); // respawn enemy

            fragColor = ExtractedEnemyData;      
        }
        if (storeData(fragCoord, ProjectileData))
        {
            vec4 ExtractedProjectileData = fetchData(iChannel0, ProjectileData);
            float ShotKD = ExtractedProjectileData.w;

            float rotationTank = fetchData(iChannel0, PlayerPositionData).z;
            vec2 rotationTower = fetchData(iChannel0, WeaponData).xy;

            float keyState = texelFetch(iChannel1, ivec2(KEY_SPACE, 0), 0).x;
            if (keyState == 1.0)
            {
                if (ShotKD <= 0.0) // can shoot only after the reload
                {
                    ShotKD = ReloadKD;
                    vec3 PlayerPositionData = fetchData(iChannel0, PlayerPositionData).xyz;
                    vec3 PlayerPosition = vec3(PlayerPositionData.x, 0, PlayerPositionData.y);
                    // rotate tank, then rotate tower x/y, then apply rotation to the shooting offset
                    // TODO rewrie a small hack - moving Z-coord lower to fit the shooting offset perfectly
                    // otherwise it's a bit more on the Z-coord
                    vec3 VelocityVector = rotateY(rotationTank)*rotateY(rotationTower.x)*rotateZ(rotationTower.y)
                                          * (ShootSocketOffset + vec3(0, rotationTower.y / 2.0, 0));
                    PlayerPosition += VelocityVector;
                    ExtractedProjectileData = vec4(PlayerPosition.x, PlayerPosition.y, PlayerPosition.z, ShotKD);
                }
                fragColor = ExtractedProjectileData;
            }
            // projectile can exist only while reloading
            if (ShotKD >= 0.0)
            {
                ExtractedProjectileData.w -= iTimeDelta;
                vec3 ProjectileVelocity = fetchData(iChannel0, ProjectileVelocityData).xyz;
                ExtractedProjectileData.xyz += ProjectileVelocity * iTimeDelta * ProjectileSpeed;

                vec2 EnemyPosition = fetchData(iChannel0, EnemyData).xy;
                fragColor = ExtractedProjectileData; 
            }
            else
                fragColor = ExtractedProjectileData; 
        }
        if (storeData(fragCoord, ProjectileVelocityData))
        {
            vec3 ProjectileVelocity = fetchData(iChannel0, ProjectileVelocityData).xyz;
            float rotationTank = fetchData(iChannel0, PlayerPositionData).z;
            vec2 rotationTower = fetchData(iChannel0, WeaponData).xy;
            float ShotKD = fetchData(iChannel0, ProjectileData).w;

            if (ShotKD > 0.05) // fps dependent kostyl with the 0.05. gravity simulation
                ProjectileVelocity += GRAVITY * iTimeDelta;
            else
                ProjectileVelocity = rotateY(rotationTank) * rotateY(rotationTower.x) * rotateZ(rotationTower.y) * ShootForwardVector;
            fragColor = vec4(ProjectileVelocity, 0);
        }
        if (storeData(fragCoord, ExplosionData))
        {
            vec4 ExtractedProjectileData = fetchData(iChannel0, ProjectileData);
            float ExplosionKD = fetchData(iChannel0, ExplosionData).w;
            vec2 EnemyPosition = fetchData(iChannel0, EnemyData).xy;
            vec3 BoomLocation = fetchData(iChannel0, ExplosionData).xyz;

            // if explosion exists - timing it
            if (ExplosionKD > 0.0)
                ExplosionKD -= iTimeDelta;
            else
            {
                float ShotKD = fetchData(iChannel0, ProjectileData).w;
                if (ShotKD > 0.0)
                {
                    // hit enemy
                    if (bHasHitEnemy() == 1)
                    {
                        ExplosionKD = ExplosionFixedKD;
                        BoomLocation = vec3(ExtractedProjectileData.x, ExtractedProjectileData.y, ExtractedProjectileData.z);
                    }
                    // hit ground
                    if (ExtractedProjectileData.y <= -2.0 && ExtractedProjectileData.y >= -2.5)
                    {
                        ExplosionKD = ExplosionFixedKD;
                        BoomLocation = vec3(ExtractedProjectileData.x, ExtractedProjectileData.y + 1.0, ExtractedProjectileData.z);
                    }
                }
            }
            fragColor = vec4(BoomLocation, ExplosionKD);
        }
        if (storeData(fragCoord, Hole1))
        {
            float HolesAmount = fetchData(iChannel0, HoleData).x;
            if (HolesAmount == 0.0f)
            {
                vec3 BoomLocation = fetchData(iChannel0, ExplosionData).xyz;
                fragColor = fetchData(iChannel0, ExplosionData);
            }

        }
        if (storeData(fragCoord, HoleData))
        {
            vec4 Holes = fetchData(iChannel0, HoleData);
            float HolesAmount = fetchData(iChannel0, HoleData).x;

            vec4 ExtractedProjectileData = fetchData(iChannel0, ProjectileData);
            if (ExtractedProjectileData.y <= -2.0 && ExtractedProjectileData.y >= -2.2)
                Holes.x = 1.0f;
            fragColor = Holes;
        }
    }
}

